python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_11.json') as f:
    data = json.load(f)

# Print keys at top level
def find_savings_notes(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'savings' in k.lower() and 'note' in k.lower():
                print(f'Found at {path}.{k}')
                print(v)
            find_savings_notes(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_savings_notes(item, f'{path}[{i}]')

find_savings_notes(data)
"
